class Solution {
    public int countKDifference(int[] nums, int k) {
        Map<Integer, Integer> cnt = new HashMap<>();
        int ans = 0;
        for (int x : nums) {
            ans += cnt.getOrDefault(x - k, 0) + cnt.getOrDefault(x + k, 0);
            cnt.merge(x, 1, Integer::sum);
        }
        return ans;
    }
}

